// Forja standalone runtime: serves one exported component's endpoints and runs its jobs,
// outside Forja. Generated by "Exportar para producción"; do not edit by hand, re-export.
//
// - ctx.db: Postgres (DATABASE_URL). A component with its own database connects as its own
//   role, confined to its schema; the rest connect as the app role.
// - ctx.jobs: a queue shared by every service in the public.forja_jobs table (at least once,
//   3 attempts with backoff). Each service runs only the jobs it owns; cron via `schedule`.
// - ctx.env: the project's secrets, read from environment variables with the same names.
// - ctx.cache: in memory, per replica.
// - Forja's platform services (sign-in, storage, email, AI, realtime, payments) answer 501.
import http from "node:http";
import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import pg from "pg";
import { Cron } from "croner";

const here = path.dirname(fileURLToPath(import.meta.url));
const manifest = JSON.parse(readFileSync(path.join(here, "manifest.json"), "utf8"));
const PORT = Number(process.env.PORT ?? 3000);
const MAX_BODY_BYTES = 10 * 1024 * 1024;
const POLL_MS = Number(process.env.JOBS_POLL_MS ?? 500);
const MAX_ATTEMPTS = 3;

const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL,
  max: Number(process.env.DB_POOL_SIZE ?? 5),
  // Schema names are validated by Forja ([a-z][a-z0-9_]*), so they need no quoting here.
  ...(manifest.schema ? { options: `-c search_path=${manifest.schema}` } : {}),
});

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
    this.name = "HttpError";
  }
}

const unavailable = (service) => () => {
  throw new HttpError(501, `${service} es un servicio de la plataforma Forja y no está disponible en la exportación autónoma.`);
};

const log = (...args) => console.log(`[${manifest.component}]`, ...args);

const db = {
  query: async (sql, params = []) => (await pool.query(sql, params)).rows,
  one: async (sql, params = []) => (await pool.query(sql, params)).rows[0],
  exec: async (sql) => { await pool.query(sql); },
  async transaction(fn) {
    const client = await pool.connect();
    try {
      await client.query("begin");
      const tx = {
        query: async (sql, params = []) => (await client.query(sql, params)).rows,
        one: async (sql, params = []) => (await client.query(sql, params)).rows[0],
      };
      const result = await fn(tx);
      await client.query("commit");
      return result;
    } catch (error) {
      await client.query("rollback").catch(() => {});
      throw error;
    } finally {
      client.release();
    }
  },
};

const cacheEntries = new Map();
const cache = {
  async get(key) {
    const hit = cacheEntries.get(key);
    if (!hit) return null;
    if (hit.expires < Date.now()) { cacheEntries.delete(key); return null; }
    return hit.value;
  },
  async set(key, value, ttlSeconds = 300) {
    cacheEntries.set(key, { value: JSON.parse(JSON.stringify(value)), expires: Date.now() + ttlSeconds * 1000 });
    if (cacheEntries.size > 10_000) cacheEntries.delete(cacheEntries.keys().next().value);
  },
  async delete(key) { cacheEntries.delete(key); },
};

const knownJobs = new Set(manifest.allJobs);
async function enqueue(name, payload = null, runAt = null, dedupe = null) {
  if (!knownJobs.has(name)) throw new Error(`No existe la tarea ${name}`);
  const { rows } = await pool.query(
    "insert into public.forja_jobs (name, payload, run_at, dedupe) values ($1, $2, coalesce($3::timestamptz, now()), $4) on conflict (dedupe) do nothing returning id",
    [name, JSON.stringify(payload ?? null), runAt, dedupe],
  );
  return rows[0] ? String(rows[0].id) : null;
}

const env = Object.fromEntries(manifest.secrets.filter((name) => process.env[name] !== undefined).map((name) => [name, process.env[name]]));

function services() {
  return {
    db,
    cache,
    storage: { put: unavailable("storage"), get: unavailable("storage"), delete: unavailable("storage"), list: unavailable("storage"), url: unavailable("storage") },
    email: { send: unavailable("email") },
    ai: { chat: unavailable("ai") },
    jobs: {
      run: async (name, payload) => { await enqueue(name, payload); },
      enqueue: (name, payload) => enqueue(name, payload),
      runAt: (name, payload, when) => enqueue(name, payload, when instanceof Date ? when.toISOString() : when),
    },
    realtime: { publish: unavailable("realtime") },
    payments: { checkout: unavailable("payments"), getCheckout: unavailable("payments"), refund: unavailable("payments") },
    env,
    log,
    fail: (status, message) => { throw new HttpError(status, message); },
  };
}

const modules = new Map();
const load = (bundle) => {
  if (!modules.has(bundle)) modules.set(bundle, import(pathToFileURL(path.join(here, "bundles", bundle)).href));
  return modules.get(bundle);
};

// --- Endpoints ------------------------------------------------------------------------------

const routes = new Map(manifest.endpoints.map((e) => [`${e.method} ${e.route}`, e]));

const json = (res, status, data, extra = {}) => {
  res.writeHead(status, { "content-type": "application/json; charset=utf-8", ...extra });
  res.end(JSON.stringify(data));
};

async function readBody(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw new HttpError(413, "Petición demasiado grande");
    chunks.push(chunk);
  }
  return Buffer.concat(chunks);
}

async function handle(req, res) {
  const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);
  if (url.pathname === "/healthz") return json(res, 200, { ok: true, component: manifest.component });
  if (!url.pathname.startsWith("/_api/")) return json(res, 404, { error: "No encontrado" });
  const method = req.method === "HEAD" ? "GET" : req.method ?? "GET";
  const route = decodeURIComponent(url.pathname.slice("/_api/".length)).replace(/\/$/, "");
  const endpoint = routes.get(`${method} ${route}`);
  if (!endpoint) return json(res, 404, { error: `No existe el endpoint ${method} /_api/${route}` });
  try {
    const raw = method === "POST" ? await readBody(req) : undefined;
    const headers = Object.entries(req.headers).filter(([k, v]) => k !== "cookie" && typeof v === "string");
    const request = new Request(url, { method, headers, body: raw && raw.length ? raw : undefined });
    let body;
    if (method === "POST") {
      const type = request.headers.get("content-type") ?? "";
      if (type.includes("application/json")) body = await request.clone().json().catch(() => ({}));
      else if (type.includes("form")) body = await request.clone().formData();
      else body = await request.clone().text();
    }
    const cookies = [];
    const ctx = {
      ...services(),
      req: request,
      method,
      query: Object.fromEntries(url.searchParams),
      body,
      user: null,
      requireUser() {
        throw new HttpError(401, "El inicio de sesión de Forja no está disponible en la exportación autónoma.");
      },
      setCookie(name, value, opts) {
        if (String(name).startsWith("forja_")) return;
        cookies.push(`${encodeURIComponent(String(name))}=${encodeURIComponent(String(value))}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${opts?.maxAge ?? 3600 * 24 * 30}`);
      },
    };
    const mod = await load(endpoint.bundle);
    if (typeof mod.default !== "function") throw new Error("El endpoint no exporta una función por defecto");
    const result = await mod.default(ctx);
    if (result instanceof Response) {
      const out = Buffer.from(await result.arrayBuffer());
      const outHeaders = Object.fromEntries(result.headers.entries());
      if (cookies.length) outHeaders["set-cookie"] = cookies;
      res.writeHead(result.status, outHeaders);
      return res.end(out);
    }
    return json(res, 200, result === undefined ? null : result, cookies.length ? { "set-cookie": cookies } : {});
  } catch (error) {
    if (error instanceof HttpError || typeof error?.status === "number") return json(res, error.status, { error: error.message });
    if (error?.name === "ZodError" && Array.isArray(error.issues)) {
      const issues = error.issues.map((i) => ({ path: i.path, message: i.message }));
      return json(res, 400, { error: issues.map((i) => (i.path?.length ? `${i.path.join(".")}: ${i.message}` : i.message)).join("; "), issues });
    }
    log(`${endpoint.file}:`, error?.stack ?? error);
    return json(res, 500, { error: "Error interno" });
  }
}

// --- Jobs -----------------------------------------------------------------------------------

const ownJobs = new Map(manifest.jobs.map((j) => [j.name, j]));
const maxConcurrency = Number(process.env.MAX_CONCURRENCY ?? manifest.maxConcurrency ?? 4);
let active = 0;
let stopping = false;

async function runOne() {
  const { rows } = await pool.query(
    `update public.forja_jobs set status = 'running', attempts = attempts + 1, locked_until = now() + interval '5 minutes'
     where id = (select id from public.forja_jobs
       where name = any($1) and run_at <= now() and (status = 'queued' or (status = 'running' and locked_until < now()))
       order by id for update skip locked limit 1)
     returning id, name, payload, attempts`,
    [[...ownJobs.keys()]],
  );
  const job = rows[0];
  if (!job) return false;
  try {
    const mod = await load(ownJobs.get(job.name).bundle);
    if (typeof mod.default !== "function") throw new Error("La tarea no exporta una función por defecto");
    await mod.default({ ...services(), payload: job.payload, job: job.name });
    await pool.query("delete from public.forja_jobs where id = $1", [job.id]);
  } catch (error) {
    log(`tarea ${job.name} falló (intento ${job.attempts}):`, error?.stack ?? error);
    await pool.query(
      `update public.forja_jobs set status = case when attempts >= $2 then 'dead' else 'queued' end,
       run_at = now() + least(60, power(2, attempts)) * interval '1 second', last_error = $3, locked_until = null where id = $1`,
      [job.id, MAX_ATTEMPTS, String(error?.message ?? error).slice(0, 4000)],
    );
  }
  return true;
}

async function pump() {
  while (!stopping && active < maxConcurrency) {
    active++;
    let found = false;
    try { found = await runOne(); } catch (error) { log("cola de tareas:", error?.message ?? error); }
    finally { active--; }
    if (!found) break;
  }
}

const crons = [];
if (ownJobs.size) {
  setInterval(() => void pump(), POLL_MS).unref();
  for (const job of manifest.jobs.filter((j) => j.schedule)) {
    // Every replica schedules; the dedupe key lets only one enqueue each tick.
    crons.push(new Cron(job.schedule, { timezone: job.timezone ?? undefined }, async (self) => {
      const tick = (self.currentRun() ?? new Date()).toISOString().slice(0, 16);
      await enqueue(job.name, null, null, `${job.name}@${tick}`).catch((error) => log(`cron ${job.name}:`, error?.message ?? error));
    }));
  }
}

const server = http.createServer((req, res) => { void handle(req, res); });
server.listen(PORT, () => log(`escuchando en :${PORT} (${manifest.endpoints.length} endpoints, ${ownJobs.size} tareas)`));

async function shutdown() {
  stopping = true;
  for (const cron of crons) cron.stop();
  server.close();
  while (active) await new Promise((r) => setTimeout(r, 50));
  await pool.end();
  process.exit(0);
}
process.on("SIGTERM", shutdown);
process.on("SIGINT", shutdown);
